package com.robothygenism.platform.map;

import com.fasterxml.jackson.databind.JsonNode;
import com.robothygenism.platform.audit.AuditService;
import com.robothygenism.platform.auth.PermissionService;
import com.robothygenism.platform.auth.PlatformPrincipal;
import com.robothygenism.platform.common.ApiException;
import com.robothygenism.platform.tenancy.ScopeService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController @RequestMapping("/api/v1")
public class MapController {
  private final JdbcClient jdbc;private final ScopeService scope;private final PermissionService permissions;private final AuditService audit;
  public MapController(JdbcClient jdbc,ScopeService scope,PermissionService permissions,AuditService audit){this.jdbc=jdbc;this.scope=scope;this.permissions=permissions;this.audit=audit;}
  @GetMapping("/maps") public Map<String,Object> maps(@RequestParam(required=false)UUID projectId,Authentication auth){var p=p(auth);if(projectId!=null)scope.project(p,projectId);var spec=projectId!=null?jdbc.sql("SELECT m.*,f.name \"floorName\" FROM \"PlatformMap\" m JOIN \"Floor\" f ON f.id=m.\"floorId\" WHERE m.\"projectId\"=:project ORDER BY m.\"updatedAt\" DESC").param("project",projectId):p.superAdmin()?jdbc.sql("SELECT m.*,f.name \"floorName\" FROM \"PlatformMap\" m JOIN \"Floor\" f ON f.id=m.\"floorId\" ORDER BY m.\"updatedAt\" DESC"):jdbc.sql("SELECT m.*,f.name \"floorName\" FROM \"PlatformMap\" m JOIN \"Floor\" f ON f.id=m.\"floorId\" WHERE m.\"tenantId\"=:tenant ORDER BY m.\"updatedAt\" DESC").param("tenant",p.tenantId());var rows=spec.query().listOfRows();return page(rows);}
  @PostMapping("/maps") public Map<String,Object> create(@Valid @RequestBody CreateMap r,Authentication auth){var p=p(auth);permissions.require(p,"MAP_MANAGE");scope.project(p,r.projectId());UUID tenant=jdbc.sql("SELECT \"tenantId\" FROM \"Project\" WHERE id=:id").param("id",r.projectId()).query(UUID.class).single(),id=UUID.randomUUID();boolean floor=jdbc.sql("SELECT EXISTS(SELECT 1 FROM \"Floor\" WHERE id=:floor AND \"projectId\"=:project)").param("floor",r.floorId()).param("project",r.projectId()).query(Boolean.class).single();if(!floor)throw new ApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","Floor not found");jdbc.sql("INSERT INTO \"PlatformMap\" (id,\"tenantId\",\"projectId\",\"floorId\",name,status,\"createdAt\",\"updatedAt\") VALUES (:id,:tenant,:project,:floor,:name,'ACTIVE',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").param("id",id).param("tenant",tenant).param("project",r.projectId()).param("floor",r.floorId()).param("name",r.name()).update();return Map.of("id",id,"projectId",r.projectId(),"floorId",r.floorId(),"name",r.name());}
  @GetMapping("/maps/{id}") public Map<String,Object> detail(@PathVariable UUID id,Authentication auth){var row=jdbc.sql("SELECT * FROM \"PlatformMap\" WHERE id=:id").param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","Map not found"));scope.project(p(auth),(UUID)row.get("projectId"));return Map.of("map",row,"versions",jdbc.sql("SELECT id,version,status::text status,\"mapObjectKey\",\"mimeType\",checksum,validation,\"publishedAt\",\"createdAt\" FROM \"MapVersion\" WHERE \"mapId\"=:id ORDER BY version DESC").param("id",id).query().listOfRows());}
  @PostMapping("/maps/{id}/versions") public Map<String,Object> version(@PathVariable UUID id,@Valid @RequestBody CreateVersion r,Authentication auth){var p=p(auth);permissions.require(p,"MAP_MANAGE");var map=detail(id,auth);@SuppressWarnings("unchecked")var info=(Map<String,Object>)map.get("map");int version=jdbc.sql("SELECT COALESCE(MAX(version),0)+1 FROM \"MapVersion\" WHERE \"mapId\"=:id").param("id",id).query(Integer.class).single();UUID versionId=UUID.randomUUID();jdbc.sql("INSERT INTO \"MapVersion\" (id,\"mapId\",version,\"floorId\",\"mapObjectKey\",\"mimeType\",checksum,status,metadata,\"createdById\",\"createdAt\",\"updatedAt\") VALUES (:id,:map,:version,:floor,:key,:mime,:checksum,'DRAFT',CAST(:metadata AS jsonb),:user,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").param("id",versionId).param("map",id).param("version",version).param("floor",info.get("floorId")).param("key",r.objectKey()).param("mime",r.mimeType()).param("checksum",r.checksum()).param("metadata",r.metadata()==null?"{}":r.metadata().toString()).param("user",p.id()).update();return Map.of("id",versionId,"mapId",id,"version",version,"status","DRAFT");}
  @GetMapping("/maps/{id}/zones") public Map<String,Object> zones(@PathVariable UUID id,@RequestParam UUID versionId,Authentication auth){detail(id,auth);return page(jdbc.sql("SELECT id,\"mapVersionId\",type::text type,name,geometry,properties FROM \"Zone\" WHERE \"mapVersionId\"=:version ORDER BY type,name").param("version",versionId).query().listOfRows());}
  @PostMapping("/maps/{id}/zones") public Map<String,Object> zone(@PathVariable UUID id,@Valid @RequestBody CreateZone r,Authentication auth){var p=p(auth);permissions.require(p,"MAP_MANAGE");detail(id,auth);String status=jdbc.sql("SELECT status::text FROM \"MapVersion\" WHERE id=:version AND \"mapId\"=:map").param("version",r.mapVersionId()).param("map",id).query(String.class).optional().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","Map version not found"));if(!status.equals("DRAFT"))throw new ApiException(HttpStatus.CONFLICT,"MAP_VERSION_IMMUTABLE","Only DRAFT map versions can be edited");validateGeometry(r.type(),r.geometry());UUID zone=UUID.randomUUID();jdbc.sql("INSERT INTO \"Zone\" (id,\"mapVersionId\",type,name,geometry,properties,\"createdAt\",\"updatedAt\") VALUES (:id,:version,CAST(:type AS \"ZoneType\"),:name,CAST(:geometry AS jsonb),CAST(:properties AS jsonb),CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)").param("id",zone).param("version",r.mapVersionId()).param("type",r.type()).param("name",r.name()).param("geometry",r.geometry().toString()).param("properties",r.properties()==null?"{}":r.properties().toString()).update();return Map.of("id",zone,"mapVersionId",r.mapVersionId(),"type",r.type(),"name",r.name(),"geometry",r.geometry());}
  @PostMapping("/maps/{id}/publish") @Transactional public Map<String,Object> publish(@PathVariable UUID id,@Valid @RequestBody Publish r,Authentication auth,HttpServletRequest http){var p=p(auth);permissions.require(p,"MAP_PUBLISH");var detail=detail(id,auth);@SuppressWarnings("unchecked")var map=(Map<String,Object>)detail.get("map");var version=jdbc.sql("SELECT status::text status FROM \"MapVersion\" WHERE id=:version AND \"mapId\"=:map FOR UPDATE").param("version",r.versionId()).param("map",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RESOURCE_NOT_FOUND","Map version not found"));if(!version.get("status").equals("DRAFT")&&!version.get("status").equals("VALIDATING"))throw new ApiException(HttpStatus.CONFLICT,"MAP_VERSION_IMMUTABLE","Map version cannot be published");long cleaning=jdbc.sql("SELECT COUNT(*) FROM \"Zone\" WHERE \"mapVersionId\"=:id AND type='CLEANING'").param("id",r.versionId()).query(Long.class).single();if(cleaning==0)throw new ApiException(HttpStatus.CONFLICT,"MAP_VALIDATION_FAILED","At least one cleaning zone is required");jdbc.sql("UPDATE \"MapVersion\" SET status='ARCHIVED',\"updatedAt\"=CURRENT_TIMESTAMP WHERE \"mapId\"=:map AND status='PUBLISHED'").param("map",id).update();jdbc.sql("UPDATE \"MapVersion\" SET status='PUBLISHED',validation=CAST(:validation AS jsonb),\"publishedAt\"=CURRENT_TIMESTAMP,\"updatedAt\"=CURRENT_TIMESTAMP WHERE id=:id").param("validation","{\"valid\":true}").param("id",r.versionId()).update();var result=Map.<String,Object>of("mapId",id,"versionId",r.versionId(),"status","PUBLISHED","reason",r.reason());audit.record(p,http,"MAP_VERSION_PUBLISH","MapVersion",r.versionId(),(UUID)map.get("tenantId"),(UUID)map.get("projectId"),version,result);return result;}
  private void validateGeometry(String type,JsonNode geometry){if(geometry==null||!geometry.hasNonNull("type")||!geometry.has("coordinates"))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_GEOMETRY","GeoJSON geometry requires type and coordinates");String expected=SetHolder.POINTS.contains(type)?"Point":"Polygon";if(!expected.equals(geometry.get("type").asText()))throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_GEOMETRY",type+" requires "+expected);}
  private PlatformPrincipal p(Authentication a){return (PlatformPrincipal)a.getPrincipal();}private Map<String,Object> page(java.util.List<Map<String,Object>> rows){return Map.of("items",rows,"total",rows.size(),"page",1,"pageSize",rows.size());}
  private static final class SetHolder{static final java.util.Set<String> POINTS=java.util.Set.of("CHARGING","STANDBY");}
  public record CreateMap(UUID projectId,UUID floorId,@NotBlank String name){}public record CreateVersion(@NotBlank String objectKey,@NotBlank String mimeType,@NotBlank String checksum,JsonNode metadata){}public record CreateZone(UUID mapVersionId,@NotBlank String type,@NotBlank String name,JsonNode geometry,JsonNode properties){}public record Publish(UUID versionId,@NotBlank String reason){}
}



